style.css:
@-moz-document url("https://www.archiveofourown.org") {
/* Error Message
     Purple-pink background.
     White-grey text */
.error,
.comment_error,
.kudos_error,
.alert.flash {
  background: #c57ea6;
  border: 1px solid #c57ea6;
  border-radius: 3px;
  color: #d3deda;
  box-shadow: none;
  padding: .643em;
  margin: .643em auto;
  }
  /* Draft 
     Background light grey with blue highlight */
  .draft {
  background-color: #303036
  }
}
